  **************************************************************************
  * @file     main.c
  * @brief    AT32A423 工具头从控 (TH) Bootloader 主程序 (MiniMCProto v2.0)
  **************************************************************************
  */

#include "at32a423_clock.h"
#include "tmr.h"
#include "usart.h"
#include "flash.h"
#include "iap.h"

/**
  * @brief  冷启动与跨复位握手及超时跳转决断逻辑
  */
static void boot_check_and_wait_handshake(void)
{
  bool is_app_valid = bsp_flash_app_integrity_check();
  volatile uint32_t *p_flag = (volatile uint32_t *)BOOT_UPGRADE_FLAG_ADDR;
  bool is_req_by_app = (*p_flag == BOOT_UPGRADE_MAGIC);

  /* 检查是否由 App 0x1D 软复位触发升级 */
  if (is_req_by_app)
  {
    *p_flag = 0U; /* 立即清除魔数，防止后续意外重启误入升级态 */
    LOG_INFO("Reboot triggered by App (0x1D UPGD). Staying in Bootloader.");
    return;
  }

  if (!is_app_valid)
  {
    LOG_ERR("App integrity check FAILED! Staying in Bootloader recovery mode.");
    return;
  }

  LOG_INFO("App integrity VALID. Listening %ums for MiniMCProto v2.0 request...",
           (unsigned int)BOOT_NORMAL_TIMEOUT_MS);
  uint32_t start_tick = tmr_get_tick();
  while ((tmr_get_tick() - start_tick) < BOOT_NORMAL_TIMEOUT_MS)
  {
    iap_upgrade_app_handle();
    if (iap_is_upgrade_active())
    {
      LOG_INFO("MiniMCProto v2.0 session active. Staying in Bootloader.");
      return;
    }
  }

  LOG_INFO("Window timeout with NO upgrade session. Safe jumping to App...");
  app_load(APP_START_ADDR);
}

/**
  * @brief  主程序入口
  */
int main(void)
{
  /* 步骤 1: 配置 150MHz 系统时钟 (PWC 1.3V, Flash 4等待周期) */
  system_clock_config();

  /* 步骤 2: 配置 NVIC 优先级分组 */
  nvic_priority_group_config(NVIC_PRIORITY_GROUP_4);

  /* 步骤 3: 初始化 SysTick 1ms 定时时基与协议状态机 */
  tmr_init();
  iap_init();

  /* 步骤 4: 初始化双串口 */
  bsp_uart3_init(USART3_BAUDRATE_DEBUG); /* 调试输出口: PC4/PC5 @ 115200 */
  bsp_uart1_init(USART1_BAUDRATE_MC);    /* 板间升级口: PB6/PB7 @ 921600 */

  LOG_INFO("==================================================");
  LOG_INFO("  AT32A423 Toolhead (TH) Bootloader v%s (MiniMC v2.0)", BL_VERSION_STR);
  LOG_INFO("  Build Date : %s", BL_BUILD_TIMESTAMP);
  LOG_INFO("  Flash Size : %u KB (App Max: %u KB)",
           (unsigned int)(FLASH_TOTAL_SIZE / 1024U),
           (unsigned int)(APP_MAX_SIZE / 1024U));
  LOG_INFO("  App Base   : 0x%08X | Anchor: 0x%08X",
           (unsigned int)APP_START_ADDR,
           (unsigned int)TRAILER_ANCHOR_ADDR);
  LOG_INFO("  Board ID   : 0x%08X", (unsigned int)BOARD_ID_TH);
  LOG_INFO("==================================================");

  /* 步骤 5: 执行冷启动握手与跳转决断 */
  boot_check_and_wait_handshake();

  /* 步骤 6: 持续运行 MiniMCProto v2.0 升级状态机主循环 */
  while (1)
  {
    iap_upgrade_app_handle();
  }
}

